import{_ as s,C as t,c as i,o as l,aa as o,G as r}from"./chunks/framework.Cn7WEiMX.js";const u=JSON.parse('{"title":"插件安装","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/setup/base-plugin-settings/installation.md","filePath":"wiki/Dynmap/setup/base-plugin-settings/installation.md"}'),c={name:"wiki/Dynmap/setup/base-plugin-settings/installation.md"};function d(p,e,f,g,m,h){const a=t("NolebaseGitContributors"),n=t("NolebaseGitChangelog");return l(),i("div",null,[e[0]||(e[0]=o('<h1 id="插件安装" tabindex="-1">插件安装 <a class="header-anchor" href="#插件安装" aria-label="Permalink to &quot;插件安装&quot;">​</a></h1> <p>本页以简洁明了的方式讲述了如何安装 Dynamp，同时将其开放给玩家。社区贡献的视频教程请在本页末查询。<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p> <h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2> <ul><li>本页假设你是 Minecraft 服主，使用的版本及核心种类均符合本插件的安装要求。所有支持的版本及核心类型可以在<a href="./../../home">主页</a>找到。</li> <li>本页假设你已拥有对操作系统或映射方式的相关知识，能够安装插件并开放/请求端口。</li> <li>本页假设你使用的 Dynmap 是官方发布的最新版本。<a href="./../../home">主页</a>可以找到下载链接。</li></ul> <h2 id="开始" tabindex="-1">开始 <a class="header-anchor" href="#开始" aria-label="Permalink to &quot;开始&quot;">​</a></h2> <ol><li><strong>关闭你的 Minecraft 服务器。</strong> 你可能想要用诸如 <code>/reload</code> 或 <code>/dynmap reload</code> ...的命令。但<strong>请不要</strong>使用 <code>/reload</code> 命令，因为它会搞坏很多东西，并且这些命令自其出现就饱受诟病。如果你改动了配置文件，你也可以重启服务器来应用改动。希望未来的版本中 <code>/dynmap reload</code> 命令会更加稳定。</li> <li>**下载 Dynmap 插件。**一般的下载地址，如 <a href="https://www.curseforge.com/minecraft/mc-mods/dynmapforge" target="_blank" rel="noreferrer">CurseForge 上的模组版本</a>，<a href="https://www.spigotmc.org/resources/dynmap.274/" target="_blank" rel="noreferrer">Spigot</a>、<a href="https://dev.bukkit.org/projects/dynmap" target="_blank" rel="noreferrer">Bukkit</a>，或是 <a href="https://github.com/webbukkit/dynmap/releases" target="_blank" rel="noreferrer">Github 发行版页面</a>。</li> <li><strong>添加 Dynmap 插件。</strong> 将下载好的 Dynmap-.jar 放入服务器的 <code>/plugins/</code> 或 <code>/mods/</code> 文件夹中。</li> <li><strong>启动服务器。</strong></li> <li><strong>验证是否安装。</strong> 插件文件夹会出现一个 <code>dynmap</code> 文件夹，其内有一个 <code>configuration.txt</code> 文件。这个文件包含了插件的绝大部分设置，但可能对你而言有些复杂，并且有些部分的配置可能你自始至终都不需要改动。这个文件的相关文档可以在 <a href="https://github.com/webbukkit/dynmap/wiki/Configuration.txt" target="_blank" rel="noreferrer">Configuration.txt</a> 章节找到。</li> <li><strong>端口转发。</strong> 大部分用户会败在这一步，我将这部分按服务器类型分为几个小步骤，以便你更好地阅读。</li> <li><strong>面板服</strong> 大部分服务器托管商只允许一个端口（用于 Minecraft 服务器），但允许用户“请求”开放其他端口。一般可以提交工单解决，但你需要根据服务器提供商的规则自行研究。如果他们允许你选择，你可以使用 8123，这是 Dynmap 的默认端口。但通常情况下你获得的是随机端口。例如，你的服务器托管商给你开放了 7229 端口。这时，你就要前往 configuration.txt，将第 322 行的 <code>webserver-port: 8123</code> 改成 <code>webserver-port: 7229</code>。请确保在改动之后重启服务器，之后你可以通过 <code>http://&lt;服务器 IP&gt;:7229</code> 打开网页地图。假如你的服务器 IP 是 <code>192.192.192.192:25565</code>，那么你在浏览器输入的地址就是 <code>http://192.192.192.192:7229</code>。这样 Dynmap 的网页服务器就会运行在这个端口上，你可以阅读下一步教程了。</li> <li><strong>VPS</strong> VPS 提供商数量繁多，“标准”各有区别，难以在本章节详细讲述 Minecraft 服务器的相关信息。如果你使用的是共享 IP 地址，你可以联系服务器提供商为你开放一个端口。如果你使用的是独立 IP 地址，只需保持默认设置，打开浏览器并输入地址 <code>http://&lt;服务器 IP&gt;:8123</code> 即可浏览。如果你的共享 VPS 有多个端口，只需按上文所述修改配置文件并在浏览器中按对应链接打开即可。当你能够正常访问网页地图时，你就可以浏览下一步。</li> <li><strong>自托管</strong> 这种情况下你通常拥有的是独立 IP。如果你没有，你如何搭建 Minecraft 服务器？希望你还记得如何转发 Minecraft 服务器的方法。如果你不幸忘记，你可以在<a href="https://portforward.com/" target="_blank" rel="noreferrer">这里</a>找到相关教程。打开端口并确保能够通过网址 <code>http://&lt;服务器 IP&gt;:8123</code> 连上网页服务器即可。再强调一次，如果你的服务器 IP 是 <code>192.192.192.192:255565</code>，那么服务器网页地图的地址是 <code>http://192.192.192.192.8123</code>。当你能够正常访问网页地图时，你就可以浏览下一步。</li> <li><strong>遇到问题？</strong> 别担心，你不是第一个在这节骨眼上碰到问题的人。网络搭建确实恼人，但我对其有着自己的理解。首先，检查你的服务器日志并确保 Dynmap 正常载入。如果它能够正常启动，服务器日志里应该会显示这样一行文字： <code>[dynmap] Web server started on address 0.0.0.0:8123</code>。如果出现错误，很有可能是端口已经被占用，或者操作系统上的防火墙出现了问题。这些问题因篇幅过长难以概括在本章教程，因此建议联系 Dynmap 团队获取帮助。如果 Dynmap 正常启动，且日志里没有相关报错，这有可能是端口转发出现了问题，或者防火墙出现了问题。首先，前往 <a href="https://www.canyouseeme.org/" target="_blank" rel="noreferrer">canyouseeme.org</a>，输入你的 IP 地址与端口号。它会检查端口号是否开放。有关这个网站的含义、操作方法和潜在风险可在<a href="https://portforward.com/" target="_blank" rel="noreferrer">这里</a>浏览。如果你还有其他问题，或还是不能成功开放端口，请联系 Dynmap 团队获取帮助。</li></ol> ',12)),r(a),r(n),e[1]||(e[1]=o('<hr class="footnotes-sep"> <section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>原视频出自 YouTube，且适用平台均为国外服务器提供商，因此略去这些内容。 <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',3))])}const b=s(c,[["render",d]]);export{u as __pageData,b as default};
